```python
import sympy as sp

# Define the range for the perfect squares
perfect_squares_range = 2023

# Function to check if a number is a perfect square
def is_perfect_square(n):
    if n <= 1:
        return False
    if n == 1:
        return True
    if n % 2 == 0:
        return False
    if n % 3 == 0:
        return False
    if n % 4 == 0:
        return False
    if n % 5 == 0:
        return True
    return n == 1

