    if n % 2 == 0:
        return False
    if n % 3 == 0:
        return False
    if n % 4 == 0:
        return False
    if n % 5 == 0:
        return True
    return n == 1

# Find all perfect squares less than 2023
perfect_squares_list = []
for n in range(perfect_squares_range):
    if is_perfect_square(n):
        perfect_squares_list.append(n)

# Check if each perfect square is divisible by 5
for i in range(perfect_squares_list):
    if is_divisible_by_5(i):
        perfect_squares_list.append(i)

print(perfect_squares_list)
```
